<?php require 'config.php'; if(!isset($_SESSION['user'])){header('Location:login.php');exit;} $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $title=trim($_POST['title']??''); $description=trim($_POST['description']??''); $link=trim($_POST['link']??''); $tag=$_POST['tag']??'other'; $imageName=null; if(!empty($_FILES['image']['name'])){ $allowed=['jpg','jpeg','png','webp','gif']; $ext=strtolower(pathinfo($_FILES['image']['name'], PATHINFO_EXTENSION)); if(!in_array($ext,$allowed)){ $err='Недопустимый формат изображения'; } else { if(!is_dir(__DIR__.'/uploads')){ mkdir(__DIR__.'/uploads',0775,true);} $imageName=uniqid('img_').'.'.$ext; if(!move_uploaded_file($_FILES['image']['tmp_name'], __DIR__.'/uploads/'.$imageName)){ $err='Не удалось загрузить файл'; } } } if(!$err){ $st=$pdo->prepare('INSERT INTO projects (title,description,image,link,tag) VALUES (?,?,?,?,?)'); $st->execute([$title,$description,$imageName,$link,$tag]); header('Location: projects.php'); exit; } } ?>
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Добавить проект</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css"><link rel="stylesheet" href="style.css"></head><body><?php include 'navbar.php'; ?><div class="container mt-4 fade-in"><h2>Добавить проект</h2><?php if(!empty($err)):?><div class="alert alert-danger"><?= $err ?></div><?php endif; ?><form method="post" enctype="multipart/form-data" class="row g-3"><div class="col-12"><label class="form-label">Название</label><input name="title" class="form-control" required></div><div class="col-12"><label class="form-label">Описание</label><textarea name="description" rows="4" class="form-control" required></textarea></div><div class="col-md-6"><label class="form-label">Ссылка (опционально)</label><input name="link" class="form-control" placeholder="https://..."></div><div class="col-md-6"><label class="form-label">Тег проекта</label><select name="tag" class="form-select"><option value="web">Web</option><option value="3D">3D</option><option value="other" selected>Другое</option></select></div><div class="col-12 mb-2"><label class="form-label">Изображение</label><div id="drop-area" class="border border-primary p-4 text-center rounded bg-dark text-light"><p class="mb-2">Перетащите картинку сюда или кликните для выбора</p><input type="file" name="image" id="fileElem" class="d-none" accept="image/*"><button type="button" class="btn btn-primary" onclick="document.getElementById('fileElem').click();">Выбрать файл</button><div id="preview" class="mt-3"></div></div></div><div class="col-12"><button class="btn btn-primary">Сохранить</button></div></form></div><script>const dropArea=document.getElementById('drop-area'); const fileInput=document.getElementById('fileElem'); const preview=document.getElementById('preview'); function showPreview(file){ const img=document.createElement('img'); img.style.maxHeight='160px'; img.src=URL.createObjectURL(file); preview.innerHTML=''; preview.appendChild(img);} dropArea.addEventListener('click',()=>fileInput.click()); dropArea.addEventListener('dragover',e=>{e.preventDefault(); dropArea.classList.add('dragover');}); dropArea.addEventListener('dragleave',()=>dropArea.classList.remove('dragover')); dropArea.addEventListener('drop',e=>{e.preventDefault(); dropArea.classList.remove('dragover'); const f=e.dataTransfer.files[0]; if(f){ fileInput.files=e.dataTransfer.files; showPreview(f);} }); fileInput.addEventListener('change',()=>{ if(fileInput.files[0]) showPreview(fileInput.files[0]); });</script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>